// --- SENDER LOGIC ---
        let chunks = [];
        let currentChunk = 0;
        let interval = null;
        let speed = 250;
        let isPlaying = true;
        let currentSenderMode = 'text'; // 'text' or 'file'
        let filePayload = null; // Stores processed file data string
        function switchMode(mode) {
            document.querySelectorAll('.mode-btn').forEach(b => b.classList.remove('active'));
            if (mode === 'send') {
                document.querySelector('button[onclick="switchMode(\'send\')"]').classList.add('active');
                document.getElementById('sender-ui').classList.remove('hidden');
                document.getElementById('receiver-ui').classList.add('hidden');
                if (html5QrCode) stopScanning(); // Ensure scanner stops if switching
            } else {
                document.querySelector('button[onclick="switchMode(\'receive\')"]').classList.add('active');
                document.getElementById('sender-ui').classList.add('hidden');
                document.getElementById('receiver-ui').classList.remove('hidden');
                // Pause sender if active
                if (interval) clearInterval(interval);
                isPlaying = false;
                updatePlayPauseIcon();
            }
        }
        function setSenderType(type) {
            currentSenderMode = type;
            document.querySelectorAll('.tab-btn').forEach(b => b.classList.remove('active'));
            document.getElementById(`tab-${type}`).classList.add('active');
            if (type === 'text') {
                document.getElementById('input-text-group').classList.remove('hidden');
                document.getElementById('input-file-group').classList.add('hidden');
            } else {
                document.getElementById('input-text-group').classList.add('hidden');
                document.getElementById('input-file-group').classList.remove('hidden');
            }
        }
        function handleFileSelect(input) {
            const file = input.files[0];
            if (!file) return;
            const status = document.getElementById('file-status');
            status.innerHTML = `Selected: <b>${file.name}</b> (${(file.size / 1024).toFixed(1)} KB)<br>Type: ${file.type || 'bin'}`;
            status.classList.remove('hidden');
            if (file.size > 200 * 1024) {
                alert("Warning: Large files (>200KB) will generate thousands of QR codes and take a very long time to transfer. We recommend <50KB for best results.");
            }
        }
        async function processInput() {
            if (currentSenderMode === 'text') {
                const text = document.getElementById('data-input').value;
                if (!text) return null;
                return `TEXT||${text}`; // Prefix for Text mode
            } else {
                const fileInput = document.getElementById('file-input');
                const file = fileInput.files[0];
                if (!file) return null;
                // Update Button State
                const btn = document.getElementById('tx-btn');
                const originalText = btn.innerHTML;
                btn.innerHTML = `<svg class="w-4 h-4 animate-spin inline-block mr-2" fill="none" viewBox="0 0 24 24"><circle class="opacity-25" cx="12" cy="12" r="10" stroke="currentColor" stroke-width="4"></circle><path class="opacity-75" fill="currentColor" d="M4 12a8 8 0 018-8v4a4 4 0 00-4 4H4z"></path></svg> Processing & Compressing...`;
                try {
                    // 1. Read File
                    const arrayBuffer = await file.arrayBuffer();
                    const uint8 = new Uint8Array(arrayBuffer);
                    // 2. Compress (GZIP) using fflate
                    const compressed = fflate.gzipSync(uint8);
                    // 3. Convert to Base64
                    const base64 = u8ToBase64(compressed);
                    // 4. Construct Protocol String: FILE|filename|mime|base64
                    // We replace pipe in mime just in case
                    const safeMime = (file.type || 'application/octet-stream').replace('|', '');
                    const safeName = file.name.replace('|', '_');
                    btn.innerHTML = originalText;
                    return `FILE|${safeName}|${safeMime}|${base64}`;
                } catch (e) {
                    console.error(e);
                    alert("Error processing file.");
                    btn.innerHTML = originalText;
                    return null;
                }
            }
        }
        // Utility: Uint8Array to Base64
        function u8ToBase64(u8) {
            let binary = '';
            const len = u8.byteLength;
            for (let i = 0; i < len; i++) {
                binary += String.fromCharCode(u8[i]);
            }
            return window.btoa(binary);
        }
        // Utility: Base64 to Uint8Array
        function base64ToU8(b64) {
            const binary = window.atob(b64);
            const len = binary.length;
            const bytes = new Uint8Array(len);
            for (let i = 0; i < len; i++) {
                bytes[i] = binary.charCodeAt(i);
            }
            return bytes;
        }
        async function calculateChecksum() {
            if (currentSenderMode !== 'text') return; // Only hash text input visually
            const data = document.getElementById('data-input').value;
            const label = document.getElementById('fingerprint');
            if (!data) {
                label.classList.add('hidden');
                return;
            }
            // Simple visual fingerprint logic
            const msgBuffer = new TextEncoder().encode(data);
            const hashBuffer = await crypto.subtle.digest('SHA-256', msgBuffer);
            const hashArray = Array.from(new Uint8Array(hashBuffer));
            const hashHex = hashArray.map(b => b.toString(16).padStart(2, '0')).join('');
            label.innerText = `Fingerprint: ${hashHex.substring(0, 8).toUpperCase()}`;
            label.classList.remove('hidden');
        }
        async function startTransmission() {
            const payload = await processInput();
            if (!payload) return alert("Please enter data or select a file.");
            // Clear previous QR
            const container = document.getElementById('qr-container');
            container.innerHTML = "";
            // Chunk size of 200 chars allows reasonably robust QR (M level)
            // Smaller chunks = faster scanning but more chunks.
            chunks = payload.match(/.{1,200}/g) || [];
            document.getElementById('qr-display-area').classList.remove('hidden');
            document.getElementById('tx-btn').innerHTML = `<span class="animate-pulse">●</span> STREAMING ACTIVE`;
            document.getElementById('tx-btn').classList.replace('bg-emerald-600', 'bg-slate-800');
            document.getElementById('chunk-total').innerText = chunks.length;
            currentChunk = 0;
            isPlaying = true;
            updatePlayPauseIcon();
            playStream();
            // Scroll to player
            document.getElementById('qr-display-area').scrollIntoView({ behavior: 'smooth' });
        }
        function playStream() {
            if (interval) clearInterval(interval);
            if (!isPlaying) return;
            renderFrame(); // Render immediately
            interval = setInterval(() => {
                currentChunk = (currentChunk + 1) % chunks.length;
                renderFrame();
            }, speed);
        }
        function renderFrame() {
            const container = document.getElementById('qr-container');
            container.innerHTML = ""; // Clear for new frame
            // Payload format: "Index|Total|Data"
            const payload = `${currentChunk + 1}|${chunks.length}|${chunks[currentChunk]}`;
            // Create QR
            new QRCode(container, {
                text: payload,
                width: 280,
                height: 280,
                colorDark: "#000000",
                colorLight: "#ffffff",
                correctLevel: QRCode.CorrectLevel.M
            });
            // UI Updates
            document.getElementById('chunk-idx').innerText = currentChunk + 1;
            const progress = ((currentChunk + 1) / chunks.length) * 100;
            document.getElementById('progress-bar').style.width = `${progress}%`;
        }
        function updateSpeed(val) {
            speed = parseInt(val);
            document.getElementById('speed-label').innerText = `${val}ms`;
            if (isPlaying && chunks.length > 0) playStream();
        }
        function togglePlay() {
            isPlaying = !isPlaying;
            updatePlayPauseIcon();
            if (isPlaying) {
                playStream();
            } else {
                if (interval) clearInterval(interval);
            }
        }
        function updatePlayPauseIcon() {
            const playIcon = document.getElementById('play-icon');
            const pauseIcon = document.getElementById('pause-icon');
            const statusText = document.getElementById('status-text');
            const statusDot = document.getElementById('status-dot');
            if (isPlaying) {
                playIcon.classList.add('hidden');
                pauseIcon.classList.remove('hidden');
                statusText.innerText = "LIVE";
                statusText.classList.replace('text-slate-500', 'text-emerald-500');
                statusDot.classList.add('animate-pulse', 'bg-emerald-500');
                statusDot.classList.remove('bg-slate-500');
            } else {
                playIcon.classList.remove('hidden');
                pauseIcon.classList.add('hidden');
                statusText.innerText = "PAUSED";
                statusText.classList.replace('text-emerald-500', 'text-slate-500');
                statusDot.classList.remove('animate-pulse', 'bg-emerald-500');
                statusDot.classList.add('bg-slate-500');
            }
        }
        function toggleFullscreen() {
            const viewport = document.getElementById('qr-container');
            if (viewport.classList.contains('fullscreen')) {
                viewport.classList.remove('fullscreen');
            } else {
                viewport.classList.add('fullscreen');
            }
        }
        // --- RECEIVER LOGIC (Using html5-qrcode) ---
        let html5QrCode = null;
        let receivedChunks = [];
        let expectedTotalChunks = 0;
        let isScanning = false;
        async function startScanning() {
            if (isScanning) return;
            // UI Switch
            document.getElementById('scan-placeholder').classList.add('hidden');
            document.getElementById('reader').classList.remove('hidden');
            document.getElementById('stop-scan-btn').classList.remove('hidden');
            // Cleanup potential leftovers
            if (html5QrCode) {
                try { await html5QrCode.clear(); } catch (e) { }
            }
            // Initialize
            html5QrCode = new Html5Qrcode("reader");
            // Dynamic QR Box size to prevent errors on small screens
            const qrBoxSize = Math.min(250, window.innerWidth * 0.7);
            const config = {
                fps: 15,
                qrbox: { width: qrBoxSize, height: qrBoxSize },
                aspectRatio: 1.0
            };
            try {
                await html5QrCode.start(
                    { facingMode: "environment" },
                    config,
                    onScanSuccess,
                    onScanFailure
                );
                isScanning = true;
            } catch (err) {
                console.error("Error starting scanner", err);
                alert("Could not start camera. Please check permissions.");
                stopScanning();
            }
        }
        async function stopScanning() {
            if (html5QrCode && isScanning) {
                try {
                    await html5QrCode.stop();
                    await html5QrCode.clear(); // Important: remove canvas from DOM
                    html5QrCode = null;
                } catch (err) {
                    console.error("Failed to stop", err);
                }
                document.getElementById('reader').classList.add('hidden');
                document.getElementById('scan-placeholder').classList.remove('hidden');
                document.getElementById('stop-scan-btn').classList.add('hidden');
                isScanning = false;
            }
        }
        function onScanFailure(error) {
            // Standard scan failure (no QR code found), ignore to keep logs clean
        }
        function onScanSuccess(decodedText, decodedResult) {
            // Expected format: "Index|Total|Data"
            const parts = decodedText.split('|');
            if (parts.length < 3) {
                showScanFeedback("Invalid QR Format", "bg-red-500/90");
                return;
            }
            const index = parseInt(parts[0]);
            const total = parseInt(parts[1]);
            // Rejoin remainder in case data had pipes, though our protocol handles this
            const data = parts.slice(2).join('|');
            if (isNaN(index) || isNaN(total)) {
                showScanFeedback("Corrupt Data", "bg-amber-500/90");
                return;
            }
            // Visual flash for successful scan
            showScanFeedback("Chunk " + index + " Scanned", "bg-emerald-500/90");
            // Initialize buffer if first valid scan
            if (expectedTotalChunks === 0 || expectedTotalChunks !== total) {
                expectedTotalChunks = total;
                receivedChunks = new Array(total).fill(null);
                initChunkGrid(total);
                document.getElementById('reception-status').classList.remove('hidden');
            }
            // Store chunk (convert 1-based index to 0-based)
            if (receivedChunks[index - 1] === null) {
                receivedChunks[index - 1] = data;
                updateReceptionUI(index - 1);
            }
            // Check if complete
            const validChunks = receivedChunks.filter(c => c !== null).length;
            if (validChunks === expectedTotalChunks) {
                finishReception();
            }
        }
        function showScanFeedback(msg, colorClass) {
            const el = document.getElementById('scan-feedback');
            el.innerText = msg;
            el.className = `absolute top-4 left-1/2 transform -translate-x-1/2 text-white text-xs px-3 py-1 rounded-full font-bold shadow-lg z-20 ${colorClass}`;
            el.classList.remove('hidden');
            // Auto hide
            setTimeout(() => {
                el.classList.add('hidden');
            }, 1000);
        }
        function initChunkGrid(total) {
            const grid = document.getElementById('chunk-grid');
            grid.innerHTML = '';
            for (let i = 0; i < total; i++) {
                const dot = document.createElement('div');
                dot.className = 'chunk-dot';
                dot.id = `chunk-dot-${i}`;
                grid.appendChild(dot);
            }
        }
        function updateReceptionUI(receivedIndex) {
            // Update Progress Bar
            const validCount = receivedChunks.filter(c => c !== null).length;
            const percent = Math.round((validCount / expectedTotalChunks) * 100);
            document.getElementById('rx-progress-bar').style.width = `${percent}%`;
            document.getElementById('rx-progress-text').innerText = `${percent}%`;
            // Update Grid Dot
            const dot = document.getElementById(`chunk-dot-${receivedIndex}`);
            if (dot) dot.classList.add('received');
        }
        function finishReception() {
            stopScanning();
            const fullPayload = receivedChunks.join('');
            document.getElementById('rx-result-container').classList.remove('hidden');
            // Celebration UI
            const status = document.getElementById('reception-status');
            status.classList.remove('bg-slate-50', 'border-slate-200');
            status.classList.add('bg-emerald-50', 'border-emerald-200');
            // --- PROTOCOL PARSING ---
            if (fullPayload.startsWith('TEXT||')) {
                // Handle Text
                document.getElementById('text-result-area').classList.remove('hidden');
                document.getElementById('file-download-area').classList.add('hidden');
                document.getElementById('rx-output').value = fullPayload.substring(6); // Remove prefix
            } else if (fullPayload.startsWith('FILE|')) {
                // Handle File: FILE|name|mime|base64
                const parts = fullPayload.split('|');
                // parts[0] = FILE
                // parts[1] = filename
                // parts[2] = mime
                // parts[3] = base64 data
                const filename = parts[1];
                const mime = parts[2];
                const base64 = parts[3];
                try {
                    // Decode Base64 -> Uint8Array
                    const compressedBytes = base64ToU8(base64);
                    // Decompress (Gunzip)
                    const originalBytes = fflate.gunzipSync(compressedBytes);
                    // Create Blob
                    const blob = new Blob([originalBytes], { type: mime });
                    const url = URL.createObjectURL(blob);
                    // Setup Download Button
                    document.getElementById('text-result-area').classList.add('hidden');
                    const dlArea = document.getElementById('file-download-area');
                    dlArea.classList.remove('hidden');
                    const btn = document.getElementById('download-link');
                    btn.href = url;
                    btn.download = filename;
                    document.getElementById('rx-file-name').innerText = `${filename} (${(blob.size / 1024).toFixed(1)} KB)`;
                } catch (e) {
                    console.error("Decompression error", e);
                    alert("Error reassembling file. Checksum failed.");
                }
            } else {
                // Fallback for legacy text
                document.getElementById('text-result-area').classList.remove('hidden');
                document.getElementById('file-download-area').classList.add('hidden');
                document.getElementById('rx-output').value = fullPayload;
            }
        }
        function copyToClipboard() {
            const copyText = document.getElementById("rx-output");
            copyText.select();
            document.execCommand("copy");
            alert("Payload copied to clipboard");
        }
